#include <stdio.h>

int main() {
    int a, b;
    scanf("%d %d", &a, &b);

    /* / 和 % 是同一优先级，都按整数规则算。
       负数时 C 是「向零截断」：-7 / 2 = -3，-7 % 2 = -1。 */
    int q = a / b;
    int r = a % b;

    printf("%d\n%d\n", q, r);
    return 0;
}

#include <stdio.h>

int main() {
    int a, b;
    scanf("%d %d", &a, &b);

    /* 关系表达式的值就是 1（真）或 0（假），可以直接用 %d 打印。
       注意相等判断是 ==，写成 = 就成了赋值，能编译但结果永远不对。 */
    printf("%d\n", a > b);
    printf("%d\n", a == b);
    printf("%d\n", a < b);
    return 0;
}

#include <stdio.h>

int main() {
    int a, b;
    scanf("%d %d", &a, &b);

    /* 关键在顺序：&& 从左往右算且会短路，
       b == 0 时左边为假，右边的 a / b 根本不会执行，
       所以这里不会触发「除以 0」崩溃。 */
    if (b != 0 && a / b > 1) {
        printf("yes\n");
    } else {
        printf("no\n");
    }
    return 0;
}

#include <stdio.h>

int main() {
    int n;
    scanf("%d", &n);

    int count = 0;
    /* n & 1 只留下最低位：是 1 就记一次。
       每轮把 n 右移一位，让下一位轮到最低位上来。
       这里只处理非负整数：负数右移会补 1，永远变不成 0。 */
    while (n > 0) {
        if (n & 1) {
            count++;
        }
        n >>= 1;
    }

    printf("%d\n", count);
    return 0;
}

