#include <stdio.h>

int main() {
    int a, b, c;
    scanf("%d %d %d", &a, &b, &c);

    /* 第一行：* 比 + 优先，先算 b * c。 */
    printf("%d\n", a + b * c);

    /* 第二行：括号把加法提到最前面，结果通常完全不同。 */
    printf("%d\n", (a + b) * c);

    /* 第三行：/ 和 % 同级、都比 + 高，所以先各算各的再相加；
       整数除法会截断，余数的符号跟着被除数，两项都可能是负数。 */
    printf("%d\n", a / c + b % c);
    return 0;
}

